var PENDING_KEY = "favi-pd-survey-pending";
var CFG = window.FaviSurveyConfig || {};
var SCRIPT_BASE = (function () {
  var s = document.currentScript && document.currentScript.src;
  return s ? s.replace(/[^\/]*$/, "") : "";
})();
if (CFG.imgOld === undefined && CFG.useRepoImages) CFG.imgOld = SCRIPT_BASE + "img/old-dashboard.png";
if (CFG.imgNew === undefined && CFG.useRepoImages) CFG.imgNew = SCRIPT_BASE + "img/new-dashboard.png";

/* ---------- odeslání odpovědí do Google Sheetu (Apps Script) ---------- */
function post(body) {
  // text/plain = "simple request" bez CORS preflightu; no-cors → odpověď se nečte
  return fetch(CFG.endpoint || ENDPOINT, {
    method: "POST",
    mode: "no-cors",
    headers: { "Content-Type": "text/plain;charset=utf-8" },
    body: body
  });
}
function readPending() {
  try { return JSON.parse(localStorage.getItem(PENDING_KEY) || "[]"); } catch (e) { return []; }
}
function writePending(list) {
  try {
    if (list.length) localStorage.setItem(PENDING_KEY, JSON.stringify(list));
    else localStorage.removeItem(PENDING_KEY);
  } catch (e) {}
}
function sendWithRetry(body, tries) {
  return post(body).catch(function () {
    if (tries > 1) return new Promise(function (r) { setTimeout(r, 1500); }).then(function () { return sendWithRetry(body, tries - 1); });
    throw new Error("send failed");
  });
}
window.FaviSurveySubmit = function (payload) {
  var body = JSON.stringify({
    lang: payload.lang,
    answers: payload.answers,
    text: payload.text,
    columns: payload.columns || [],
    hp: ""
  });
  sendWithRetry(body, 3).catch(function () {
    // Bez připojení: odpověď uložit v prohlížeči a odeslat při další návštěvě
    var list = readPending(); list.push(body); writePending(list);
  });
};
function flushPending() {
  var list = readPending();
  if (!list.length) return;
  writePending([]);
  list.forEach(function (body) {
    post(body).catch(function () { var l = readPending(); l.push(body); writePending(l); });
  });
}

