var DETAIL_DIV = ["Podeľte sa s nami o viac detailov","Podělte se s námi o více detailů"];
function uxMatrices(prefix) {
  return ["A", "B", "C"].map(function (f) {
    var items = UXQ.filter(function (x) { return x.f === f; });
    return { id:prefix + f, type:"matrix", kind:"agree", bare:true, divider:f === "A" ? DETAIL_DIV : null, q:UX_HEAD[f], ends:UX_ENDS[f], levels:UX_LEVELS[f],
      rows:items.map(function (x) { return x.n; }),
      topics:items.map(function (x) { return x.t; }) };
  });
}

