var app = document.getElementById("app");
var S = { lang:"cz", step:0, a:{}, draft:false };
var saveTimer = null;

function detectLang(saved) {
  var h = (location.hash || "").replace("#", "").toLowerCase();
  if (h === "sk" || h === "cz" || h === "en") return h;
  if (saved && (saved.lang === "sk" || saved.lang === "cz" || saved.lang === "en")) return saved.lang;
  return "cz";
}
function loadSaved() {
  try { var raw = localStorage.getItem(STORE_KEY); return raw ? JSON.parse(raw) : null; } catch (e) { return null; }
}
function save() {
  if (S.step > NSEC + 2) return;
  try { localStorage.setItem(STORE_KEY, JSON.stringify({ lang:S.lang, step:S.step || S.resume || 0, a:S.a })); } catch (e) {}
}
function saveSoon() { clearTimeout(saveTimer); saveTimer = setTimeout(save, 300); }
function clearSaved() { try { localStorage.removeItem(STORE_KEY); } catch (e) {} }

