  var confetti = CONFETTI.map(function (c) {
    return '<i class="cf" style="left:' + c[0] + "%;top:" + c[1] + "%;width:" + c[5] + "px;height:" + (c[3] === "c" ? c[5] : Math.round(c[5] * 0.45)) +
      "px;border-radius:" + (c[3] === "c" ? "50%" : "2px") + ";background:" + c[4] + ";transform:rotate(" + c[2] + 'deg)"></i>';
  }).join("");
  var when = (S.a.cwhen !== undefined) ? answerText(callQ("cwhen")) : "";
  var tsel = S.a.ctopics || [], tq = callQ("ctopics");
  var topics = tsel.map(function (i) { return esc(T(tq.opts[+i])); }).join("<br>");
  var withUx = !tsel.length || tsel.indexOf("0") > -1, withSales = !tsel.length || tsel.indexOf("1") > -1;
  var who = (withUx ? [esc(T(THANKS.vUx))] : []).concat(withSales ? [esc(T(THANKS.vSales))] : []).join("<br>");
